=== submission_03.ino ===
   1| // ECE Lab 3 - hardware PWM on D5
   2| //
   3| // D5 -> P1.13
   4| // I compute the register values from the clock so I don't hardcode magic numbers.
   5| //
   6| //   CORE_CLK   = 64 MHz (nRF52840 runs at 64 MHz)
   7| //   PRESCALER  = 16  -> 64 MHz / 16 = 4 MHz tick
   8| //   TOP        = 4 MHz / 1 kHz = 4000
   9| //   DUTY       = TOP / 4 = 1000  (25%)
  10| //
  11| // TOP fits in the 15-bit COUNTERTOP register (max 32767).
  12| 
  13| #include <Arduino.h>
  14| 
  15| #define CORE_CLK_HZ   64000000UL
  16| #define PRESC_DIV     16UL
  17| #define TARGET_HZ     1000UL
  18| 
  19| #define PWM_TOP_VAL   (CORE_CLK_HZ / PRESC_DIV / TARGET_HZ)
  20| #define PWM_DUTY_VAL  (PWM_TOP_VAL / 4)
  21| 
  22| static uint16_t seq_values[] = { (uint16_t)(PWM_DUTY_VAL | 0x8000) };
  23| 
  24| void setup() {
  25|   NRF_PWM2->PSEL.OUT[0] = (1 << PWM_PSEL_OUT_PORT_Pos) | (13 << PWM_PSEL_OUT_PIN_Pos);
  26|   NRF_PWM2->PSEL.OUT[1] = PWM_PSEL_OUT_CONNECT_Disconnected << PWM_PSEL_OUT_CONNECT_Pos;
  27|   NRF_PWM2->PSEL.OUT[2] = PWM_PSEL_OUT_CONNECT_Disconnected << PWM_PSEL_OUT_CONNECT_Pos;
  28|   NRF_PWM2->PSEL.OUT[3] = PWM_PSEL_OUT_CONNECT_Disconnected << PWM_PSEL_OUT_CONNECT_Pos;
  29| 
  30|   NRF_PWM2->ENABLE     = 1;
  31|   NRF_PWM2->MODE       = PWM_MODE_UPDOWN_Up;
  32|   NRF_PWM2->PRESCALER  = PWM_PRESCALER_PRESCALER_DIV_16;
  33|   NRF_PWM2->COUNTERTOP = PWM_TOP_VAL;
  34|   NRF_PWM2->LOOP       = 0;
  35|   NRF_PWM2->DECODER    = PWM_DECODER_LOAD_Common | (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  36| 
  37|   NRF_PWM2->SEQ[0].PTR      = (uint32_t)seq_values;
  38|   NRF_PWM2->SEQ[0].CNT      = 1;
  39|   NRF_PWM2->SEQ[0].REFRESH  = 0;
  40|   NRF_PWM2->SEQ[0].ENDDELAY = 0;
  41| 
  42|   NRF_PWM2->TASKS_SEQSTART[0] = 1;
  43| }
  44| 
  45| void loop() {}
</student_code>
